"""Poll ONLY original W130 UUIDs; preserve every completed result and status history."""
from __future__ import annotations

from concurrent.futures import ThreadPoolExecutor, as_completed
from datetime import datetime, timezone
from pathlib import Path
import json
import subprocess

HERE = Path(__file__).resolve().parent
BRIDGE = Path(r"<USER_HOME>\AppData\Local\WebAgentGPT\bin\webagent.cmd")


def utc():
    return datetime.now(timezone.utc).isoformat()


def call(command: str, job_id: str) -> dict:
    try:
        p = subprocess.run([str(BRIDGE), command, job_id, "--json"],
                           capture_output=True, text=True, timeout=100, shell=False)
        try:
            parsed = json.loads(p.stdout)
        except ValueError:
            parsed = None
        return {"command": command, "exitCode": p.returncode, "body": parsed,
                "stdout": p.stdout if parsed is None else None, "stderr": p.stderr}
    except Exception as exc:
        return {"command": command, "error": repr(exc)}


def harvest(receipt: Path) -> dict:
    original = json.loads(receipt.read_text(encoding="utf-8"))
    job_id = original["response"]["id"]
    stem = receipt.name.removesuffix(".submission.json")
    result_path = HERE / f"{stem}.result.json"
    status = call("status", job_id)
    body = status.get("body") or {}
    state = body.get("state") if isinstance(body, dict) else None
    out = {"utc": utc(), "stem": stem, "uuid": job_id, "state": state or "ERROR",
           "status": status, "resultSaved": result_path.exists()}
    if state == "COMPLETED" and not result_path.exists():
        result = call("result", job_id)
        out["retrieval"] = {"exitCode": result.get("exitCode"), "error": result.get("error")}
        if result.get("exitCode") == 0 and result.get("body") is not None:
            with result_path.open("x", encoding="utf-8") as f:
                json.dump({"uuid": job_id, "stem": stem, "utc": utc(),
                           "serviceResult": result["body"]}, f, indent=2, ensure_ascii=False)
            out["resultSaved"] = True
    return out


if __name__ == "__main__":
    receipts = sorted(HERE.glob("*.submission.json"))
    with ThreadPoolExecutor(max_workers=10) as pool:
        futures = [pool.submit(harvest, path) for path in receipts]
        results = [f.result() for f in as_completed(futures)]
    results.sort(key=lambda x: x["stem"])
    with (HERE / "status-history.jsonl").open("a", encoding="utf-8") as f:
        for row in results:
            f.write(json.dumps(row, ensure_ascii=False) + "\n")
    (HERE / "harvest-latest.json").write_text(
        json.dumps({"observedUtc": utc(), "results": results}, indent=2, ensure_ascii=False), encoding="utf-8")
    for row in results:
        print(json.dumps({k: row[k] for k in ("stem", "uuid", "state", "resultSaved")}), flush=True)

