"""Poll the original Wave133 UUIDs; never submits jobs or overwrites original results."""
import concurrent.futures, json, pathlib, subprocess
from datetime import datetime, timezone

HERE=pathlib.Path(__file__).resolve().parent
BRIDGE=pathlib.Path(r'<USER_HOME>\AppData\Local\WebAgentGPT\bin\webagent.cmd')
def now(): return datetime.now(timezone.utc).isoformat()
def call(command, job):
    p=subprocess.run([str(BRIDGE),command,job,'--json'],capture_output=True,text=True,encoding='utf-8',timeout=60,shell=False)
    try: body=json.loads(p.stdout)
    except ValueError: body=None
    return {'exitCode':p.returncode,'body':body,'stderr':p.stderr,'unparsedStdout':p.stdout if body is None else None}
def poll(path):
    receipt=json.loads(path.read_text(encoding='utf-8'))
    stem=receipt['stem']; job=(receipt.get('response') or {}).get('id')
    if not job:return {'stem':stem,'state':'NO_UUID_INSPECT_ATTEMPT'}
    row={'utc':now(),'stem':stem,'uuid':job}
    result=HERE/(stem+'.result.json')
    if result.exists():
        saved=json.loads(result.read_text(encoding='utf-8'))
        body=saved.get('serviceResult') or {}
        valid=saved.get('uuid')==job==body.get('id') and body.get('state')=='COMPLETED' and isinstance(body.get('response'),str)
        return dict(row,state='SAVED_COMPLETED' if valid else 'SAVED_RESULT_INVALID',resultSaved=valid,observation='LOCAL_RECEIPT_ONLY_NO_SERVICE_POLL')
    try:
        status=call('status',job); row['status']=status
        row['state']=(status.get('body') or {}).get('state','ERROR')
        if row['state']=='COMPLETED' and not result.exists():
            retrieved=call('result',job); body=retrieved.get('body') or {}
            if retrieved['exitCode']==0 and body.get('id')==job and body.get('state')=='COMPLETED' and isinstance(body.get('response'),str):
                with result.open('x',encoding='utf-8') as f:json.dump({'uuid':job,'stem':stem,'utc':now(),'serviceResult':body},f,indent=2,ensure_ascii=False)
            else:row['retrievalError']=retrieved
        row['resultSaved']=result.exists()
    except Exception as e:row.update(state='OBSERVATION_ERROR',error=repr(e))
    return row
if __name__=='__main__':
    paths=sorted(HERE.glob('*.submission.json'))
    with concurrent.futures.ThreadPoolExecutor(max_workers=10) as pool:rows=list(pool.map(poll,paths))
    snapshot={'observedUtc':now(),'results':rows}
    (HERE/'harvest-latest.json').write_text(json.dumps(snapshot,indent=2,ensure_ascii=False),encoding='utf-8')
    with (HERE/'status-history.jsonl').open('a',encoding='utf-8') as f:
        for row in rows:f.write(json.dumps(row,ensure_ascii=False)+'\n')
    for row in rows:print(json.dumps({k:row[k] for k in ['stem','uuid','state','resultSaved','error'] if k in row}),flush=True)

